import fs from 'node:fs';
import path from 'node:path';

import { profile } from '../profile';

export const codegenHeader = `/**
 * DO NOT MODIFY
 * @danger This file is generated by the ${profile.scriptName} script.
*/`;

/**
 * A value as a TypeScript literal with single-quoted strings, the style of the generated files.
 * The strings are escaped, so that no text in them (a description from Figma, say) can end the
 * string and become code.
 */
export const toSingleQuotedLiteral = (value: unknown) =>
  JSON.stringify(value, null, 2).replace(
    /"((?:[^"\\]|\\.)*)"/g,
    (_string, inner: string) => `'${inner.replace(/\\"/g, '"').replace(/'/g, "\\'")}'`,
  );

export const writeFile = (filePath: string, content: string | Uint8Array) =>
  fs.writeFileSync(filePath, content);

/** Replaces a directory with an empty one. */
export const resetDirectory = (directory: string) => {
  if (fs.existsSync(directory)) fs.rmSync(directory, { recursive: true });
  fs.mkdirSync(directory, { recursive: true });
};

/** Resolves an SVG path, or undefined if the name escapes `outputSvgPath`. */
export const resolveSvgPath = (outputSvgPath: string, svgName: string): string | undefined => {
  const root = path.resolve(outputSvgPath);
  const resolved = path.resolve(root, `${svgName}.svg`);
  return resolved.startsWith(root + path.sep) ? resolved : undefined;
};
